import subprocess
import os

# Assuming the application uses a routing decorator pattern similar to the context
def route(path):
    def decorator(f):
        f._route = path
        return f
    return decorator

@route('/ping/<url>')
def ping(url):
    """
    Executes a system ping command for the provided URL and returns the output.
    """
    # Using subprocess to run the ping command safely
    # -c 4 limits the ping to 4 packets
    try:
        output = subprocess.check_output(['ping', '-c', '4', url], stderr=subprocess.STDOUT)
        return output.decode('utf-8')
    except subprocess.CalledProcessError as e:
        return e.output.decode('utf-8')
```

