def get_processes_using_file(file_path):
    """
    Invoke the fuser command to identify processes using the specified file.
    """
    try:
        # fuser returns process IDs to stderr by default
        result = subprocess.run(['fuser', file_path], capture_output=True, text=True)
        if result.returncode == 0:
