import subprocess

def get_executable_path(command_name):
    """
    Determines the executable path for a given command name using 'which'.
    """
    try:
        result = subprocess.check_output(['which', command_name], stderr=subprocess.STDOUT)
        return result.decode('utf-8').strip()
    except subprocess.CalledProcessError:
        return None
