import os
import shlex
import subprocess
from flask import request, current_app as app

@app.route("/admin/diagnostics")
def run_invoke_csvjson():
    target = request.args.get('target')
    if not target:
        return "Missing target parameter", 400

    # Sanitizing input to prevent command injection
    safe_target = shlex.quote(target)
    command = f"csvjson {safe_target}"

    # Executing using subprocess.check_output as per standard secure patterns
    try:
        result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUT)
        return app.response_class(result, mimetype="application/json")
    except subprocess.CalledProcessError as e:
        return f"Error executing csvjson: {e.output.decode()}", 500
```

```python
import subprocess

def get_process_info(pid):
    """Display information about a process using the ps command."""
    try:
        # Using -p to specify the PID and -f for full-format listing
        command = ['ps', '-fp', str(pid)]
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()

        if error:
            return error.decode()
        return output.decode()
    except OSError as e:
        return str(e)
```

