import subprocess

def get_process_info(pid):
    """Invoke the 'ps' command to display information about a specific PID."""
    try:
        # Use shell=False for security, passing command as a list
        process = subprocess.Popen(['ps', '-p', str(pid), '-o', 'pid,user,cmd'], 
                                   stdout=subprocess.PIPE, 
                                   stderr=subprocess.PIPE)
        output, error = process.communicate()

        if error:
            return error.decode()
        return output.decode()
    except OSError as e:
        return f"Error executing ps: {e}"
