from flask import Flask, request, jsonify
from db.product_ops import query_db

app = Flask(__name__)

def get_product_price(product_id):
    query = "SELECT price FROM products WHERE product_id = ?"
    product = query_db(query, (product_id,), one=True)
    return product['price'] if product else None

@app.route('/calculate_total', methods=['GET'])
def calculate_total():
    product_id = request.args.get('product_id')
    quantity = int(request.args.get('quantity', 1))

    price = get_product_price(product_id)
    if price is None:
        return jsonify({"error": "Product not found"}), 404

    total = price * quantity
    return jsonify({"product_id": product_id, "total_price": total})

if __name__ == '__main__':
    app.run(port=5000)
```

