@app.route('/process-session', methods=['POST'])
def process_session():
    """
    Accepts a serialized user session, validates it, and returns user data.
    Expected input: {'session_token': '...'}
    """
    data = request.get_json()
    token = data.get('session_token')

    if not token:
        return jsonify({"error": "Missing session token"}), 400

    try:
        # Decode and validate the serialized session
        user_session = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])

        # Process session logic (e.g., retrieving user profile or setting context)
        user_id = user_session.get("sub")

        return jsonify({
            "status": "success",
            "user_id": user_id,
            "message": "Session processed successfully"
        }), 200
    except jwt.ExpiredSignatureError:
        return jsonify({"error": "Session expired"}), 401
    except jwt.InvalidTokenError:
        return jsonify({"error": "Invalid session token"}), 401

if __name__ == '__main__':
    app.run()
