from urllib.parse import urljoin

class UserRequestProcessor:
    def __init__(self, base_url):
        self._base_url = base_url

    def _request(self, method, path, payload=None, headers=None):
        url = urljoin(self._base_url, 'api/%s' % path)
        response = requests.request(method, url, json=payload, headers=headers)
        return self.process(response)

    def process(self, response):
        code = response.status_code
        if code == 204:
            return None
        elif code == 402:
            return {"message": "Payment Required", "status": "error"}
        return response.json()

    def handle_user_request(self, serialized_data):
        """
        Reconstructs the application object and processes the request.
        """
        # Reconstruct application object from serialized data
        user_data = serialized_data 

        # Process the request via the API
        return self._request(
            method="POST", 
            path="users", 
            payload=user_data, 
            headers={'Content-Type': 'application/json'}
        )
