def get_order_summary(order_xml):
    """
    Reconstructs an order summary from serialized XML data.
    """
    import xml.etree.ElementTree as ET

    root = ET.fromstring(order_xml)
    summary = {
        "valid": root.attrib.get("valid") == "true",
        "items": []
    }

    for child in root:
        summary["items"].append({
            "type": child.tag,
            "message": child.text
        })

    return summary
