            return {"purchases": [], "status": "empty"}

        data = response.json()

        # Transform serialized data into a dashboard-ready format
        dashboard_data = {
            "user_id": data.get("userId"),
            "history": [
                {
                    "id": item.get("caseId"),
                    "summary": item.get("subject"),
                    "date": item.get("timeCreated"),
                    "status": item.get("status")
                }
                for item in data.get("purchases", [])
            ],
            "status": "success"
        }
        return dashboard_data

    except Exception as e:
        return {"status": "error", "message": str(e)}
