import ConfigParser

def get_app_settings(config_file, section, variable, cache_manager):
    """
    Retrieves a serialized configuration from cache, reconstructs the 
    configuration, and returns the specific application setting.
    """
    cached_config = cache_manager.get(variable)

    if cached_config:
        return cached_config

    value = get_config_value(config_file, section, variable)

    if value:
        cache_manager.set(variable, value)

    return value

def get_config_value(config_file, section, variable):
    """ extracts a config file value """
    try:
        parser = ConfigParser.SafeConfigParser()
        parser.read(config_file)
        return parser.get(section, variable)
    except:
        return None
