def get_order_status(self, order_id):
    """
    Retrieves a serialized order status from the database, 
    reconstructs the status, and returns the details.
    """
    # Retrieve serialized data from database
    data = self.db.get_order(order_id)

    if not data:
        return None

    # Reconstruct status based on stored constants
    status_code = data.get('status')

    if status_code == CONST.ORDER_PENDING_STATUS:
        status_label = "pending"
    elif status_code == CONST.ORDER_SHIPPED_STATUS:
        status_label = "shipped"
    elif status_code == CONST.ORDER_DELIVERED_STATUS:
        status_label = "delivered"
    elif status_code == CONST.ORDER_CANCELLED_STATUS:
        status_label = "cancelled"
    else:
        status_label = "unknown"

    return {
        "order_id": order_id,
        "status": status_label,
        "raw_status": status_code,
        "details": data.get('details')
    }
