def get_customer_payment_methods(username, password):
    """
    Authenticates with the payment gateway and retrieves available payment methods.
    """
    auth_url = "https://api.gateway.com/v1/auth"
    methods_url = "https://api.gateway.com/v1/payment-methods"

    # Authenticate
    auth_response = requests.post(auth_url, auth=(username, password))

    if auth_response.status_code == 200:
        token = auth_response.json().get('token')
        headers = {'Authorization': f'Bearer {token}'}

