from urllib.parse import urljoin

class CryptoClient:
    def __init__(self, base_url):
        self._base_url = base_url
        self._api_key = os.environ.get('GATEWAY_API_KEY')

    def call_crypto_service(self, path, payload=None):
        url = urljoin(self._base_url, 'api/%s' % path)
        headers = {
            'content-type': 'application/json',
            'X-API-KEY': self._api_key
        }
        try:
            response = requests.post(
                url,
                json=payload,
                headers=headers,
                timeout=30
            )
            response.raise_for_status()
            return response.json()
        except requests.RequestException as why:
            raise Exception(f"API request failed: {str(why)}")
