def connect_authenticates_geolocation():
    """Authenticate with the geolocation service and validate user coordinates."""
    api_token = request.headers.get("X-API-KEY")

    if not api_token or api_token != GEO_API_TOKEN:
        return jsonify({"error": "Unauthorized"}), 401

    lat = request.args.get("lat")
    lon = request.args.get("lon")

    if not lat or not lon:
        return jsonify({"error": "Missing coordinates"}), 400

    # Validation logic for coordinates
    try:
        if -90 <= float(lat) <= 90 and -180 <= float(lon) <= 180:
            return jsonify({"status": "success", "message": "Coordinates validated"})
        else:
            return jsonify({"error": "Invalid coordinate range"}), 400
    except ValueError:
        return jsonify({"error": "Invalid coordinate format"}), 400
