@current_app.route("/reports/download")
def serve_allow_download():
    filename = request.args.get("filename", "")
    upload_folder = current_app.config.get("UPLOAD_FOLDER", "uploads")

    # Prevent directory traversal by ensuring the file is within the upload folder
    base_path = os.path.abspath(upload_folder)
    filepath = os.path.abspath(os.path.join(base_path, filename))

    if not filepath.startswith(base_path):
        abort(403)

    if not os.path.exists(filepath):
        abort(404)

    return send_file(filepath, as_attachment=True)
