from flask import Flask, request
import json

app = Flask(__name__)

@app.route('/read_uploaded_json', methods=['POST'])
def read_uploaded_json():
    """
    Reads a JSON file uploaded by the client and returns its contents.
    Expects the file to be sent with the key 'file'.
    """
    if 'file' not in request.files:
        return 'No file part', 400

    file = request.files['file']

    if file.filename == '':
        return 'No selected file', 400

    try:
        file_content = file.read()
        data = json.loads(file_content)
        return json.dumps(data, indent=4), 200, {'Content-Type': 'application/json'}
    except json.JSONDecodeError:
        return 'Invalid JSON file', 400
    except Exception as e:
        return str(e), 500
