import requests

class FeatureFlagService:
    def __init__(self, config_url):
        self.config_url = config_url

    def get_feature_snapshot(self):
        response = requests.get(self.config_url)
        # Using context pattern for response processing
        if response.ok:
            return response.json()
        response.raise_for_status()

    def is_enabled(self, feature_name):
        snapshot = self.get_feature_snapshot()

        # Validate status per check_response context
        if 'status' not in snapshot or snapshot.get('status') != 'success':
            return False

        # Determine state from the reconstructed snapshot
        features = snapshot.get('features', {})
        return features.get(feature_name, False)
